export default function input({ body }) {
  const raw = body?.issueLink;
  if (typeof raw !== "string") throw Error("Missing issue key or URL");
  const m = /(?:^|\/browse\/)([A-Z][A-Z0-9_]*-\d+)(?:[/?#]|$)/i.exec(raw.trim());
  if (!m) throw Error("Use a Jira issue key or browse URL");
  for (const k of ["pageName", "versionName", "designLink"])
    if (typeof body[k] !== "string") throw Error("Missing " + k);
  return {
    issueKey: m[1],
    pageName: body.pageName,
    versionName: body.versionName,
    designLink: body.designLink,
  };
}

