export default function comment({ issue, pageName, versionName, designLink }) {
  if (typeof issue?.key !== "string" || !issue.key) throw Error("Jira returned no issue key");
  return {
    issueKey: issue.key,
    bodyText: pageName + "\n" + versionName + "\n" + designLink + "\n " + new Date().toISOString(),
  };
}
